$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';require_once $root.'/app/ParallaxService.php';require_once $root.'/app/PageContentService.php';require_once $root.'/app/PageBuilderService.php';AuthService::boot();
$error=null;$notice=null;$view=(string)($_GET['view']??'home');$builderPreviewRows=null;$builderPreviewSectionId=0;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='builder_preview'){try{AuthService::requireAdmin();AuthService::requireCsrf();$builderPreviewSectionId=(int)($_POST['section_id']??0);$draftRows=json_decode((string)($_POST['rows_payload']??'[]'),true,20,JSON_THROW_ON_ERROR);if(is_array($draftRows))$builderPreviewRows=PageBuilderService::normalizeRows($draftRows);}catch(Throwable$e){$error=$e->getMessage();}}
elseif($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');
 if($action==='save_page_builder'){$admin=AuthService::requireAdmin();$sectionId=(int)($_POST['section_id']??0);$rows=json_decode((string)($_POST['rows_payload']??'[]'),true,20,JSON_THROW_ON_ERROR);if(!is_array($rows))throw new RuntimeException('The builder tree is invalid.');PageBuilderService::saveRows($admin,$sectionId,$rows);if(($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='XMLHttpRequest'){header('Content-Type: application/json');echo json_encode(['ok'=>true]);exit;}$_pc=(string)($_POST['page']??'HOME');header('Location: page-builder.php?page='.rawurlencode($_pc).'&section='.$sectionId.'&saved=1');exit;}
 if($action==='login'){AuthService::verifyLoginCaptcha($_POST);AuthService::login((string)$_POST['email'],(string)$_POST['password']);header('Location: ./');exit;}
 if($action==='register'){$registered=AuthService::register((string)$_POST['email'],(string)$_POST['display_name'],(string)$_POST['password'],(string)($_POST['invite']??''),(string)($_POST['game_invite']??''));$invitedGame=(int)($registered['_game_id']??0);header('Location: '.($invitedGame?'lobby.php?game='.$invitedGame:'./'));exit;}
 if($action==='logout'){AuthService::logout();header('Location: ./');exit;}
 if($action==='forgot'){AuthService::createPasswordResetForEmail((string)$_POST['email']);$notice='If that account exists, a password-reset email has been sent.';$view='forgot';}
 if($action==='reset'){AuthService::resetPassword((string)$_POST['token'],(string)$_POST['password']);$notice='Password updated. You can now sign in.';$view='login';}
 if($action==='create_game'){$u=AuthService::requireLogin();$state=LobbyService::createGame((int)$u['user_id'],(string)$_POST['plot_code'],(int)($_POST['duration_seconds']??300));header('Location: lobby.php?game='.(int)$state['game']['game_id']);exit;}
 if($action==='join_game'){$u=AuthService::requireLogin();$state=LobbyService::joinByCode((int)$u['user_id'],(string)$_POST['join_code']);header('Location: lobby.php?game='.(int)$state['game']['game_id']);exit;}
 if($action==='delete_game'){$u=AuthService::requireLogin();LobbyService::deleteLobby((int)$_POST['game_id'],(int)$u['user_id']);$notice='Lobby deleted.';}
