}catch(Throwable$e){$error=$e->getMessage();}}
$user=AuthService::currentUser();$publicPages=['how_it_works'=>'HOW_IT_WORKS','stories'=>'STORIES','create'=>'CREATE','about'=>'ABOUT'];$isPublicHome=$view==='public'||(!$user&&$view==='home');$isStoryDetail=$view==='story';$isPublicPage=isset($publicPages[$view]);$isPublicSite=$isPublicHome||$isPublicPage||$isStoryDetail;$captchaMode=AuthService::captchaMode();$captchaSiteKey=$captchaMode==='GOOGLE'?AuthService::setting('GOOGLE_RECAPTCHA_SITE_KEY'):'';$plots=[];$games=[];$durationOptions=[];$publicStories=[];$storyDetail=null;$parallaxLayers=$isPublicHome?ParallaxService::all():[];$homeContent=$isPublicHome?PageContentService::keyed('HOME'):[];$pageContent=$isPublicPage?PageContentService::keyed($publicPages[$view]):[];$socials=$isPublicSite?PageContentService::socials():[];if($builderPreviewRows!==null&&$builderPreviewSectionId>0){$encodedRows=json_encode($builderPreviewRows,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);foreach($homeContent as&$previewSection)if((int)($previewSection['site_page_section_id']??0)===$builderPreviewSectionId)$previewSection['rows_json']=$encodedRows;unset($previewSection);foreach($pageContent as&$previewSection)if((int)($previewSection['site_page_section_id']??0)===$builderPreviewSectionId)$previewSection['rows_json']=$encodedRows;unset($previewSection);}
if($isPublicSite){$publicStories=db()->query('SELECT p.plot_id,p.code,p.title,p.genre,p.setting_name,p.scenario_text,p.max_players,COALESCE(pop.play_count,0) play_count,(SELECT pm.file_path FROM plot_media_assets pm WHERE pm.plot_id=p.plot_id AND pm.active=1 AND pm.placement="PRIMARY" ORDER BY pm.sort_order,pm.media_asset_id LIMIT 1) primary_image_path,(SELECT pm.file_path FROM plot_media_assets pm WHERE pm.plot_id=p.plot_id AND pm.active=1 AND pm.placement IN ("OPENING","SCENE","TURNING_POINT") ORDER BY FIELD(pm.placement,"OPENING","SCENE","TURNING_POINT"),pm.sort_order,pm.media_asset_id LIMIT 1) fallback_image_path FROM plots p LEFT JOIN (SELECT s.plot_id,COUNT(DISTINCT g.game_id) play_count FROM simulations s JOIN games g ON g.simulation_id=s.simulation_id WHERE g.status IN ("RUNNING","COMPLETE") AND g.deleted_at_utc IS NULL GROUP BY s.plot_id) pop ON pop.plot_id=p.plot_id WHERE p.status="active" ORDER BY play_count DESC,p.title')->fetchAll();foreach($publicStories as&$story){$story['image_path']=$story['primary_image_path']?:$story['fallback_image_path'];if($isStoryDetail&&hash_equals((string)$story['code'],(string)($_GET['code']??'')))$storyDetail=$story;}unset($story);}
if($user){$q=db()->query('SELECT code,title,genre,setting_name,max_players FROM plots WHERE status="active" ORDER BY title');$plots=$q->fetchAll();$durationOptions=db()->query('SELECT duration_seconds,label_text FROM platform_game_durations WHERE active=1 ORDER BY sort_order,duration_seconds')->fetchAll();$games=LobbyService::userGames((int)$user['user_id']);}
function csrf_field(): string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function home_field(array $content,string $section,string $field,string $fallback): string{return isset($content[$section])&&array_key_exists($field,$content[$section])?(string)$content[$section][$field]:$fallback;}
function home_style(array $content,string $section): string{return isset($content[$section])?PageContentService::style($content[$section]):'';}
function render_home_buttons(array $section,?array $user): void{$buttons=PageContentService::buttons($section);?><div class="hero-actions"><?php foreach($buttons as$button):if(!$button['visible']||$button['url']==='')continue;$href=$user&&$button['member_url']!==''?$button['member_url']:$button['url'];$target=$button['target']==='_blank'?' target="_blank" rel="noopener noreferrer"':'';?><a class="btn hero-button" data-hover-effect="<?=e($button['hover_effect'])?>" data-button-width="<?=e($button['width'])?>" style="<?=e(PageContentService::buttonStyle($button))?>" href="<?=e($href)?>"<?=$target?>><?=e($button['label'])?></a><?php endforeach;?></div><?php }
function render_social_links(array $socials): void{?><nav class="public-social-links" aria-label="Toinky social media"><?php foreach($socials as$social):if($social['url']==='')continue;?><a href="<?=e($social['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($social['label'])?></a><?php endforeach;?></nav><?php }
function public_story_excerpt(string $text,int $maxChars=190): string{$text=trim($text);if(mb_strlen($text)<=$maxChars)return $text;$truncated=mb_substr($text,0,$maxChars);$lastSpace=mb_strrpos($truncated,' ');if($lastSpace!==false&&$lastSpace>$maxChars*0.5)$truncated=mb_substr($truncated,0,$lastSpace);return rtrim($truncated," \t\n\r\0\x0B.,;:!?").'…';}function public_optimized_image(string $path,string $version='MEDIUM'): string{$path=trim($path);if($path==='')return '';if(str_starts_with($path,'/theme-media.php'))return $path;return '/theme-media.php?path='.rawurlencode($path).'&version='.$version;}
function public_image_srcset(string $path): string{$path=trim($path);if($path==='')return '';if(str_starts_with($path,'/theme-media.php'))return '';foreach(['THUMBNAIL','MEDIUM','LARGE']as$version){$srcset[]=public_optimized_image($path,$version).' '.($version==='THUMBNAIL'?'150':($version==='MEDIUM'?'600':'1200')).'w';}return implode(', ',$srcset);}

function render_story_cards_row(): void{global $publicStories;?><div class="public-story-grid public-story-row"><?php foreach(array_slice($publicStories,0,3)as$story):?><article class="public-story-card"><?php if(!empty($story['image_path'])):?><img src="<?=e(public_optimized_image((string)$story['image_path'],'MEDIUM'))?>" srcset="<?=e(public_image_srcset((string)$story['image_path']))?>" sizes="(max-width: 768px) 100vw, 400px" alt="<?=e($story['title'])?> artwork"><?php else:?><div class="story-art-placeholder" aria-hidden="true"><span><?=e(mb_substr($story['title'],0,1))?></span></div><?php endif;?><div><p class="type-public-meta"><?=e($story['genre'])?> · <?=(int)$story['play_count']?> plays</p><h2 class="type-public-card-title"><?=e($story['title'])?></h2><p class="story-card-setting type-public-meta"><?=e($story['setting_name']?:'A Toinky story world')?></p><p class="type-public-body"><?=e(public_story_excerpt((string)$story['scenario_text']))?></p><a class="public-action" href="?view=story&amp;code=<?=rawurlencode((string)$story['code'])?>">Explore This Story →</a></div></article><?php endforeach;?><?php if(!$publicStories):?><p class="type-public-intro">New story worlds are being prepared. Check back soon.</p><?php endif;?></div><?php }
function public_background_fit_style(string $prefix,string $fit): string{$fit=strtoupper($fit);return match($fit){'FIT'=>'--'.$prefix.'-bg-size:contain;--'.$prefix.'-bg-repeat:no-repeat;','TILE'=>'--'.$prefix.'-bg-size:auto;--'.$prefix.'-bg-repeat:repeat;',default=>'--'.$prefix.'-bg-size:cover;--'.$prefix.'-bg-repeat:no-repeat;'};}
function public_spacing_style(array $row,string $prefix,string $var): string{$style='';$all=(int)($row[$prefix.'_all_px']??0);foreach(['top','right','bottom','left']as$edge){$value=(($row[$prefix.'_mode']??'ALL')==='ALL')?$all:(int)($row[$prefix.'_'.$edge.'_px']??0);$style.='--'.$var.'-'.$edge.':'.$value.'px;';}return$style;}
function public_media_url(int $mediaId,string $version=''): string{$url='/theme-media.php?id='.$mediaId;if($version!=='')$url.='&version='.$version;return$url;}
function public_column_image_version(string $layout): string{$layout=strtoupper($layout);if($layout==='FOUR_COLUMN')return'THUMBNAIL';if(in_array($layout,['TWO_COLUMN','THREE_COLUMN'],true))return'MEDIUM';return'LARGE';}
function public_column_count(string $layout): int{return match($layout){'TWO_COLUMN'=>2,'FOUR_COLUMN'=>4,default=>3};}
function public_row_style(array $row): string{$style='';$layout=(string)($row['layout_type']??'TEXT_TOP');if(!empty($row['background_color']))$style.='--row-bg:'.$row['background_color'].';';if(!empty($row['background_media_id']))$style.='--row-bg-image:url("'.public_media_url((int)$row['background_media_id'],'LARGE').'");';$style.=public_background_fit_style('row',(string)($row['background_fit']??'FILL'));if((int)($row['overlay_opacity']??0)>0){$op=(int)($row['overlay_opacity']??0)/100;$hex=ltrim((string)($row['overlay_color']??''),'#');if($hex==='')$hex='1C242B';if(strlen($hex)===6){$r=hexdec(substr($hex,0,2));$g=hexdec(substr($hex,2,2));$b=hexdec(substr($hex,4,2));$style.='--row-overlay:rgba('.$r.','.$g.','.$b.','.$op.');';}}if(!empty($row['text_color']))$style.='--row-text:'.$row['text_color'].';--section-body-color:'.$row['text_color'].';--section-label-color:'.$row['text_color'].';';if(!empty($row['title_color']))$style.='--section-title-color:'.$row['title_color'].';';elseif(!empty($row['text_color']))$style.='--section-title-color:'.$row['text_color'].';';if(($row['text_align']??'left')!=='left')$style.='--row-align:'.$row['text_align'].';';if(($row['blend_mode']??'normal')!=='normal')$style.='--row-blend:'.$row['blend_mode'].';';if(($row['align_self']??'stretch')!=='stretch')$style.='--row-align-self:'.$row['align_self'].';';if(!empty($row['font_size']))$style.='--row-size:'.$row['font_size'].';';if(!empty($row['tablet_font_size']))$style.='--row-tablet-size:'.$row['tablet_font_size'].';';if(!empty($row['mobile_font_size']))$style.='--row-mobile-size:'.$row['mobile_font_size'].';';if(!empty($row['font_weight']))$style.='--row-weight:'.$row['font_weight'].';';if(($row['text_transform']??'none')!=='none')$style.='--row-transform:'.$row['text_transform'].';';$style.=public_spacing_style($row,'margin','row-margin').public_spacing_style($row,'padding','row-pad');foreach(['tablet','mobile']as$device){if(!empty($row[$device.'_padding_all_px']))$style.='--row-'.$device.'-pad-all:'.(int)$row[$device.'_padding_all_px'].'px;';if(!empty($row[$device.'_margin_all_px']))$style.='--row-'.$device.'-margin-all:'.(int)$row[$device.'_margin_all_px'].'px;';if(!empty($row[$device.'_columns']))$style.='--row-'.$device.'-columns:'.(int)$row[$device.'_columns'].';';}$style.='--row-desktop-columns:'.public_column_count($layout).';';if(!empty($row['image_width_px'])){$imageWidth=(int)$row['image_width_px'];$style.='--row-image-width:'.$imageWidth.'px;--row-image-track:minmax(0,'.$imageWidth.'px);';}if(!empty($row['image_height_px']))$style.='--row-image-height:'.(int)$row['image_height_px'].'px;';foreach(['tablet','mobile']as$device){$widthKey=$device.'_image_width_px';$heightKey=$device.'_image_height_px';if(!empty($row[$widthKey])){$imageWidth=(int)$row[$widthKey];$style.='--row-'.$device.'-image-width:'.$imageWidth.'px;--row-'.$device.'-image-track:minmax(0,'.$imageWidth.'px);';}if(!empty($row[$heightKey]))$style.='--row-'.$device.'-image-height:'.(int)$row[$heightKey].'px;';}if(!empty($row['column_background_color']))$style.='--column-bg:'.$row['column_background_color'].';';if(!empty($row['column_background_media_id']))$style.='--column-bg-image:url("'.public_media_url((int)$row['column_background_media_id'],public_column_image_version((string)($row['layout_type']??''))).'");';$style.=public_background_fit_style('column',(string)($row['column_background_fit']??'FILL'));$style.=public_spacing_style($row,'column_margin','column-margin');$style.=public_spacing_style($row,'column_padding','column-pad');if(($row['content_width']??'FULL')==='MAX'){$style.='--container-content-width:min(100%,'.(int)($row['max_width_px']??1980).'px);';$style.='--container-max-width:'.(int)($row['max_width_px']??1980).'px;';}else $style.='--container-content-width:100%;';$style.='--container-min-height:'.(int)($row['min_height_px']??0).'px;';$style.='--container-direction:'.(($row['items_direction']??'COLUMN')==='ROW'?'row':'column').';';$align=in_array(($row['align_items']??'stretch'),['flex-start','center','flex-end','stretch'],true)?$row['align_items']:'stretch';$style.='--container-align-items:'.$align.';';$style.='--container-flex-wrap:'.(!array_key_exists('wrap_items',$row)||!empty($row['wrap_items'])?'wrap':'nowrap').';';return$style;}
function public_column_style(array $column): string{$style='';if(!empty($column['background_color']))$style.='--column-bg:'.$column['background_color'].';';if(!empty($column['background_media_id']))$style.='--column-bg-image:url("'.public_media_url((int)$column['background_media_id'],'MEDIUM').'");';$style.=public_background_fit_style('column',(string)($column['background_fit']??'FILL'));$style.=public_spacing_style($column,'margin','column-margin');$hasPad=(int)($column['padding_all_px']??0)>0||(int)($column['padding_top_px']??0)>0||(int)($column['padding_right_px']??0)>0||(int)($column['padding_bottom_px']??0)>0||(int)($column['padding_left_px']??0)>0;if($hasPad)$style.=public_spacing_style($column,'padding','column-pad');return$style;}
function render_public_row(array $row,array $section,array $socials,?string $bpath=null): void{if(empty($row['active']))return;$secBg=(int)($section['background_media_id']??0);if($secBg>0){$rowBg=(int)($row['background_media_id']??0);if($rowBg===$secBg){$row['background_media_id']=null;}$row['background_color']='';}$layout=$row['layout_type']??'TEXT_TOP';$columns=$row['columns']??[];$rowImagePath=!empty($row['image_media_id'])?public_media_url((int)$row['image_media_id'],'LARGE'):(string)($section['image_path']??'');$rowStyle=public_row_style($row);if(!$columns&&in_array($layout,['TWO_COLUMN','THREE_COLUMN','FOUR_COLUMN'],true))$columns=PageContentService::columns($section);if($layout==='TWO_COLUMN')$columns=array_slice($columns,0,2);elseif($layout==='THREE_COLUMN')$columns=array_slice($columns,0,3);elseif($layout==='FOUR_COLUMN')$columns=array_slice($columns,0,4);if($layout==='CONTAINER'){?><div data-builder-path="<?=e($bpath??'')?>" class="public-container-row" style="<?=e($rowStyle)?>"><div class="public-container-inner"><?php foreach(array_values($row['children']??[]) as$ci=>$child)if(is_array($child)){$parentBg=(int)($row['background_media_id']??0);$childBg=(int)($child['background_media_id']??0);if($parentBg>0&&$childBg===$parentBg){$child['background_media_id']=null;}render_public_row($child,$section,$socials,($bpath??'').'.'.$ci);}?></div></div><?php return;}if($layout==='STORY_CARDS'){?><div data-builder-path="<?=e($bpath??'')?>" class="public-content-row layout-story-cards" style="<?=e($rowStyle)?>"><?php render_story_cards_row();?></div><?php return;}?><div data-builder-path="<?=e($bpath??'')?>" class="public-content-row layout-<?=e(strtolower(str_replace('_','-',$layout)))?>" style="<?=e($rowStyle)?>"><?php if($layout==='IMAGE_LEFT'&&!empty($rowImagePath)):?><img src="<?=e($rowImagePath)?>" alt="<?=e($section['image_alt']??'')?>"><?php endif;?><div class="public-section-copy"><?php $label=(string)($row['label_text']??$row['eyebrow_text']??'');?><?php if($label!==''):?><p class="section-label type-public-section-label"><?=e($label)?></p><?php endif;?><?php if(!empty($row['title_text'])):?><h2 class="type-public-section-title"><?=e($row['title_text'])?></h2><?php endif;?><div class="type-public-body"><?=$row['content_html']??''?></div><?php if($layout==='SOCIALS')render_social_links($socials);?><?php if(!empty($row['bullets'])):?><ul class="feature-list"><?php foreach($row['bullets'] as $bullet):?><li><?=e($bullet)?></li><?php endforeach;?></ul><?php endif;?><?php if(!empty($row['buttons'])):?><div class="hero-actions row-actions"><?php foreach($row['buttons'] as $button):if(!$button['visible']||$button['url']==='')continue;?><a class="btn hero-button" href="<?=e($button['url'])?>"><?=e($button['label'])?></a><?php endforeach;?></div><?php endif;?></div><?php if($layout==='IMAGE_RIGHT'&&!empty($rowImagePath)):?><img src="<?=e($rowImagePath)?>" alt="<?=e($section['image_alt']??'')?>"><?php endif;?><?php $columns=array_values(array_filter($columns,function($c){return!empty($c['title'])||!empty($c['text'])||!empty($c['content'])||!empty($c['image_media_id'])||!empty($c['icon_text']);}));?><?php if($columns):?><div class="public-three-columns<?= $layout==='TWO_COLUMN'?' public-two-columns':''?><?= $layout==='FOUR_COLUMN'?' public-four-columns':''?>"><?php foreach($columns as $column):?><article style="<?=e(public_column_style($column))?>"><?php if(!empty($column['icon_text'])):?><?php $_is='font-size:'.max(16,min(120,(int)($column['icon_size_px']??32))).'px;';if(!empty($column['icon_color'])&&preg_match('/^#[0-9A-F]{6}([0-9A-F]{2})?$/i',$column['icon_color']))$_is.='color:'.$column['icon_color'].';';$_al=$column['icon_align']??'left';if(!in_array($_al,['left','center','right'],true))$_al='left';?><div style="text-align:<?=e($_al)?>;"><span class="public-card-icon" aria-hidden="true" style="<?=e($_is)?>"><?=e($column['icon_text'])?></span></div><?php endif;?><?php if(!empty($column['image_media_id'])):?><img src="<?=public_media_url((int)$column['image_media_id'],public_column_image_version($layout))?>" alt="<?=e($column['alt_text']??'')?>"><?php elseif(!empty($column['image_path'])):?><img src="<?=e($column['image_path'])?>" alt="<?=e($column['alt_text']??'')?>"><?php endif;?><h3 class="type-public-card-title"><?=e($column['title']??'')?></h3><div class="type-public-body"><?=$column['content']??''?></div><?php if(!empty($column['buttons'])):?><div class="row-actions"><?php foreach($column['buttons'] as $button):if(!$button['visible']||$button['url']==='')continue;?><a class="public-action" href="<?=e($button['url'])?>"><?=e($button['label'])?></a><?php endforeach;?></div><?php endif;?></article><?php endforeach;?></div><?php endif;?></div><?php }
function public_root_container_style(array $row): string{return str_replace(['--row-bg:','--row-bg-image:','--row-bg-size:','--row-bg-repeat:','--row-pad-top:','--row-pad-right:','--row-pad-bottom:','--row-pad-left:'],['--section-bg-color:','--section-bg-image:','--section-bg-size:','--section-bg-repeat:','--section-pad-top:','--section-pad-right:','--section-pad-bottom:','--section-pad-left:'],public_row_style($row));}
function render_public_rows(array $section,array $socials): void{$rows=PageContentService::rows($section);$rootRow=$rows[0]??[];$rootIsContainer=is_array($rootRow)&&($rootRow['layout_type']??'')==='CONTAINER';if($rootIsContainer&&empty($rootRow['active']))return;$rootStyle=$rootIsContainer?public_root_container_style($rootRow):'';$renderRows=$rootIsContainer&&is_array($rootRow['children']??null)?$rootRow['children']:$rows;?><section data-builder-section="<?=e((string)($section['site_page_section_id']??''))?>" class="public-content-section managed-section-background layout-rows" style="<?=e(PageContentService::style($section).$rootStyle)?>"><div class="public-container-inner"><?php $bpi=0;foreach($renderRows as $row)if(is_array($row)){render_public_row($row,$section,$socials,(string)$bpi);$bpi++;}?></div></section><?php }
function render_public_section(array $section,array $socials): void{if(!empty($section['rows_json'])){render_public_rows($section,$socials);return;}$layout=$section['layout_type']??'IMAGE_RIGHT';$class='layout-'.strtolower(str_replace('_','-',$layout));$columns=$layout==='THREE_COLUMN'?PageContentService::columns($section):[];?><section class="public-content-section managed-section-background <?=e($class)?>" style="<?=e(PageContentService::style($section))?>"><?php if($layout==='IMAGE_LEFT'&&!empty($section['image_path'])):?><img src="<?=e($section['image_path'])?>" alt="<?=e($section['image_alt']??'')?>"><?php endif;?><div class="public-section-copy"><?php if(!empty($section['eyebrow_text'])):?><p class="section-label type-public-section-label"><?=e($section['eyebrow_text'])?></p><?php endif;?><?php if(!empty($section['title_text'])):?><h2 class="type-public-section-title"><?=e($section['title_text'])?></h2><?php endif;?><div class="type-public-body"><?=$section['content_html']??''?></div><?php if($layout==='SOCIALS')render_social_links($socials);?></div><?php if($layout==='IMAGE_RIGHT'&&!empty($section['image_path'])):?><img src="<?=e($section['image_path'])?>" alt="<?=e($section['image_alt']??'')?>"><?php endif;?><?php if($layout==='THREE_COLUMN'):?><div class="public-three-columns"><?php foreach($columns as$column):?><article><?php if(!empty($column['icon_text'])):?><?php $_is='font-size:'.max(16,min(120,(int)($column['icon_size_px']??32))).'px;';if(!empty($column['icon_color'])&&preg_match('/^#[0-9A-F]{6}([0-9A-F]{2})?$/i',$column['icon_color']))$_is.='color:'.$column['icon_color'].';';$_al=$column['icon_align']??'left';if(!in_array($_al,['left','center','right'],true))$_al='left';?><div style="text-align:<?=e($_al)?>;"><span class="public-card-icon" aria-hidden="true" style="<?=e($_is)?>"><?=e($column['icon_text'])?></span></div><?php endif;?><?php if(!empty($column['image_media_id'])):?><img src="<?=public_media_url((int)$column['image_media_id'],public_column_image_version($layout))?>" alt="<?=e($column['alt_text']??'')?>"><?php elseif(!empty($column['image_path'])):?><img src="<?=e($column['image_path'])?>" alt="<?=e($column['alt_text']??'')?>"><?php endif;?><?php if(!empty($column['title'])):?><h3 class="type-public-card-title"><?=e($column['title'])?></h3><?php endif;?><div class="type-public-body"><?=$column['content']??''?></div><?php if(!empty($column['buttons'])):?><div class="row-actions"><?php foreach($column['buttons'] as $button):if(!$button['visible']||$button['url']==='')continue;?><a class="public-action" href="<?=e($button['url'])?>"><?=e($button['label'])?></a><?php endforeach;?></div><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><?php }
